function Get-NvidDisplayTarget {
        $displayDevices = @(Get-PnpDevice -Class Display -ErrorAction SilentlyContinue | Where-Object { $_.InstanceId -match 'VEN_10DE' })
        if ($displayDevices.Count -eq 0) { throw 'No NVIDIA display adapter was detected by Windows PnP. Cannot install NVIDIA display driver automatically.' }
        $dev = $displayDevices | Select-Object -First 1
        $devId = $null
        if ($dev.InstanceId -match 'DEV_([0-9A-Fa-f]{4})') { $devId = $matches[1].ToUpperInvariant() }
        $seriesId = 131
        $productId = $null
        $productName = $dev.FriendlyName
        switch ($devId) {
            '2C02' { $productId = 1065; $productName = 'NVIDIA GeForce RTX 5080' }
            '2B85' { $productId = 1066; $productName = 'NVIDIA GeForce RTX 5090' }
            '2C05' { $productId = 1068; $productName = 'NVIDIA GeForce RTX 5070 Ti' }
            '2D04' { $productId = 1070; $productName = 'NVIDIA GeForce RTX 5070' }
        }
        if (-not $productId) {
            if ($dev.FriendlyName -match '5090') { $productId = 1066; $seriesId = 131 }
            elseif ($dev.FriendlyName -match '5080') { $productId = 1065; $seriesId = 131 }
            elseif ($dev.FriendlyName -match '5070\s*Ti') { $productId = 1068; $seriesId = 131 }
            elseif ($dev.FriendlyName -match '5070') { $productId = 1070; $seriesId = 131 }
            else { throw ("Unsupported NVIDIA adapter for automatic driver lookup: {0} ({1}). Add its DEV_* mapping to nvid." -f $dev.FriendlyName,$dev.InstanceId) }
        }
        [pscustomobject]@{ Device = $dev; DeviceId = $devId; SeriesId = $seriesId; ProductId = $productId; ProductName = $productName }
    }

if ($MyInvocation.InvocationName -ne '.') {
